-- Phase 3 template marketplace seed data.
--
-- Twelve real, distinct, fully-working multi-page templates — each row's
-- "structure" is a genuine {files, pages} payload in the exact shape
-- /api/templates/use clones into a new project (the same shape a real
-- project_versions row already has), not placeholder or seed-prompt text.
-- Generated from a small library of shared, parameterized section builders
-- (see the PR/commit description for the generation script) — the copy,
-- color theme, typography, page structure, and composition are genuinely
-- different per template, the same way this app's own AI pipeline produces
-- different sites from different prompts while sharing no literal content
-- between them.
--
-- This is a deliberately bounded, quality-first starting set, not the
-- eventual 100+/500+ target — the templates table's schema (this
-- migration's sibling, 20260829000001) and every piece of the
-- templates/list, templates/favorite, and templates/detail routes already
-- support arbitrary volume: reaching 100+ is purely a matter of inserting
-- more rows, no architecture change required.

insert into public.templates (id, category, name, description, tags, style, industry, tier_required, is_featured, structure) values
  ('b4eea137-92a9-4006-97d5-6da43cb27409', 'Startup', 'Launchpad', 'A dark, high-contrast SaaS landing page built to convert — hero, social proof stats, feature grid, and pricing.', ARRAY['saas', 'dark-mode', 'pricing', 'startup']::text[], 'modern', 'saas', 'starter', true, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-tight text-slate-900\">Launchpad</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-indigo-300\">Now in public beta</span>\n        <h1 className=\"font-sans mt-6 text-4xl font-bold leading-tight tracking-tight md:text-6xl\">Ship your product before your competitors finish their roadmap meeting.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Launchpad gives your team one place to plan, build, and ship — without the twelve tools stitched together with duct tape.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-indigo-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-indigo-400 transition-colors\">Start free trial</a>\n          <a href=\"#features\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See how it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">12k+</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Teams onboard</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">99.98%</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Uptime</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">4.9/5</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Average rating</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">40hrs</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Saved per month</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, ShieldCheck, GitBranch, Users, BarChart3, Workflow } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section id=\"features\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Everything your team needs, nothing it doesn't</h2>\n        <p className=\"mt-3 text-slate-500\">Launchpad replaces the spreadsheet, the sticky notes, and the six browser tabs.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Zap size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Instant deploys</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Push to main, live in seconds — no pipeline babysitting.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <ShieldCheck size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Enterprise-grade security</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">SOC 2 Type II, SSO, and audit logs out of the box.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <GitBranch size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Built-in version control</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Every change tracked, every rollback one click away.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Users size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Team workspaces</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Give every team its own space without losing shared context.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <BarChart3 size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Real-time analytics</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Know what's working before your competitors do.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Workflow size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Automated workflows</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Let Launchpad handle the busywork your team shouldn't.</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-sans text-2xl font-medium leading-snug text-slate-900\">&ldquo;We replaced four tools with Launchpad in a single afternoon. Our team hasn't looked back.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-full bg-indigo-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Priya Shah</p>\n          <p className=\"text-xs text-slate-500\">VP Engineering, Fieldnote</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Simple pricing, no surprises</h2>\n        <p className=\"mt-3 text-slate-500\">Start free. Upgrade when you're ready to scale.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 md:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            \n            <p className=\"mt-3 font-semibold text-slate-900\">Starter</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$0<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Up to 3 projects</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Community support</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> 1 GB storage</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full border border-slate-200 text-slate-700 hover:border-slate-400 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Starter</a>\n          </div>\n          <div className=\"rounded-2xl border border-indigo-500 shadow-lg shadow-indigo-100 p-6\">\n            <span className=\"rounded-full bg-indigo-600 px-2.5 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-white\">Most popular</span>\n            <p className=\"mt-3 font-semibold text-slate-900\">Growth</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Unlimited projects</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Priority support</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> 50 GB storage</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Advanced analytics</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full bg-indigo-600 text-white hover:bg-indigo-700 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Growth</a>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            \n            <p className=\"mt-3 font-semibold text-slate-900\">Scale</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$99<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Everything in Growth</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> SSO & audit logs</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Dedicated support</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Custom contracts</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full border border-slate-200 text-slate-700 hover:border-slate-400 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Scale</a>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Talk to our team</h2>\n      <p className=\"mt-3 text-slate-500\">Questions about Launchpad? We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-indigo-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Launchpad</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">The workspace fast-moving product teams actually enjoy using.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Product</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/pricing\" className=\"text-sm text-slate-500 hover:text-slate-900\">Pricing</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Features</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Company</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">About</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Legal</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Privacy</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Terms</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Launchpad. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-indigo-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-indigo-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"slug":"pricing","path":"/pricing","name":"Pricing","sections":["Navbar","Pricing","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
  ('4cd7fb5f-a5e6-4e1d-b412-c9ec3f6aba85', 'Agency', 'Northlight Studio', 'A bold portfolio-led agency site — split hero, project grid, and a direct path to inquiry.', ARRAY['agency', 'portfolio', 'creative', 'bold']::text[], 'bold', 'creative agency', 'pro', true, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-serif text-lg font-bold tracking-tight text-slate-900\">Northlight</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-violet-600 px-4 py-2 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-violet-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-violet-700\">Brand & product studio</span>\n          <h1 className=\"font-serif mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">We build brands people actually remember.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Northlight partners with ambitious founders to design identities, products, and campaigns that don't blend in.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-violet-600 px-6 py-3 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Start a project</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View our work</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-violet-100 to-violet-50 ring-1 ring-violet-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Work.tsx":"export default function Work() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">Selected work</h2>\n        <p className=\"mt-3 text-slate-500\">A handful of the brands we've helped find their voice.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Fieldnote — Brand identity</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Full rebrand for a Series A productivity startup.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Kindred — Product design</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">End-to-end UX for a community marketplace app.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Oatmilk Co — Packaging</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Shelf-ready packaging system for a DTC food brand.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Solace — Web design</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">A conversion-focused marketing site rebuild.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Verve Fitness — Campaign</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Launch campaign across print, digital, and OOH.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-violet-100 to-violet-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Anchor — Identity system</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Logo, type, and motion system for a fintech app.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-violet-50 to-violet-100 \" />\n        <div>\n          <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">A small studio, on purpose.</h2>\n          <p className=\"mt-4 text-slate-600\">Northlight stays intentionally small — six people, no account managers, no handoffs. The team that pitches your project is the team that ships it.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">Tell us about your project</h2>\n      <p className=\"mt-3 text-slate-500\">We take on a handful of new clients each quarter — let's see if we're a fit.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-violet-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-violet-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-violet-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-serif text-lg font-bold text-slate-900\">Northlight</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Brand and product design for founders who refuse to blend in.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Studio</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Social</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Instagram</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">LinkedIn</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Northlight. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-violet-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-violet-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Work","About","Footer"]},{"slug":"work","path":"/work","name":"Work","sections":["Navbar","Work","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
