  ('ff90c2bc-764c-4d78-a7a6-bdaa78580ec9', 'Portfolio', 'Ava Cole — Product Designer', 'A minimal, type-led personal portfolio for a designer or freelancer — project grid, about, and contact.', ARRAY['portfolio', 'freelancer', 'minimal', 'designer']::text[], 'minimal', 'design', 'free', false, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-tight text-slate-900\">Ava Cole</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/about\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">About</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-md bg-rose-600 px-4 py-2 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white text-slate-900\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-rose-300\">Product designer, based in Toronto</span>\n        <h1 className=\"font-sans mt-6 text-4xl font-bold leading-tight tracking-tight md:text-6xl\">I design software that feels obvious in hindsight.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Freelance product design for startups and design teams who want a second, senior set of eyes.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          