    <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-rose-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Solace — Mobile app</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">0 to 1 design for a mental health support app.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-rose-100 to-rose-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Anchor — Dashboard UX</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Simplified a dense fintech dashboard for daily use.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-rose-50 to-rose-100 \" />\n        <div>\n          <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">A bit about me</h2>\n          <p className=\"mt-4 text-slate-600\">I've spent nine years designing for early-stage startups, most recently as a founding designer at two YC companies. I now work with a small number of clients at a time, embedded in the team, not bolted on.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Let's work together</h2>\n      <p className=\"mt-3 text-slate-500\">Currently booking new projects starting next quarter.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-rose-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-rose-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-rose-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Ava Cole</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Freelance product design for startups and design teams.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Site</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/about\" className=\"text-sm text-slate-500 hover:text-slate-900\">About</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Elsewhere</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Dribbble</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">LinkedIn</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Ava Cole. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-rose-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-rose-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Work","Footer"]},{"slug":"about","path":"/about","name"