  ('a65fe548-aa2a-40ae-9132-ddf3d42ec262', 'Restaurant', 'Ember & Oak', 'A warm, appetite-driven restaurant site — hero, menu highlights, and reservations with hours and location.', ARRAY['restaurant', 'food', 'reservations', 'warm']::text[], 'warm', 'restaurant', 'starter', true, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-serif text-lg font-bold tracking-tight text-slate-900\">Ember & Oak</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/menu\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Menu</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Reservations</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-amber-600 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-amber-700\">Wood-fired, seasonal, downtown</span>\n          <h1 className=\"font-serif mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">Dinner worth planning your week around.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Ember & Oak is a wood-fired kitchen serving seasonal plates built around whatever's best at the market that morning.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\