50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Telehealth</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Virtual visits for follow-ups and minor concerns.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-2xl border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Visit our clinic</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">220 Maple Street, Suite 4B — free parking on-site.</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-teal-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Fri, 8:00am – 6:00pm. Sat, 9:00am – 1:00pm.</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-xl bg-gradient-to-br from-teal-100 to-teal-50\" />\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Request an appointment</h2>\n      <p className=\"mt-3 text-slate-500\">New patients typically hear back within one business day.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-teal-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-teal-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-teal-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Wellpoint Family Clinic</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Primary and family care with real time for every patient.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Care</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/services\" className=\"text-sm text-slate-500 hover:text-slate-900\">Services</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Book a visit</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Patients</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Insurance</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Patient portal</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Wellpoint Family Clinic. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-teal-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-teal-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Services","Location","Footer"]},{"slug":"services","path":"/services","name":"Services","sections":["Navbar","Services","Footer"]},{"slug":"contact","path":"/contact","name":"Book a visit","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb),
  ('2bbf02ee-08f2-4c04-a4b1-0a04ce6b8d0a', 'Travel', 'Wanderlust Tours', 'A vibrant small-group tour operator site — destination grid, trip highlights, and inquiry form.', ARRAY['travel', 'tours', 'vibrant']::text[], 'vibrant', 'travel', 'starter', false, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-tight text-slate-900\">Wanderlust</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/destinations\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Destinations</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-sky-600 px-4 py-2 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-sky-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-sky-300\">Small-group trips, 8–12 people</span>\n        <h1 className=\"font-sans mt-6 text-4xl font-bold leading-tight tracking-tight md:text-6xl\">Travel with people you'll actually want to eat dinner with.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Wanderlust runs small-group trips built around real local access — no giant tour buses, no rushed itineraries.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-sky-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-sky-400 transition-colors\">Browse trips</a>\n          <a href=\"#features\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">How it works</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Destinations.tsx":"export default function Destinations() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Upcoming trips</h2>\n        <p className=\"mt-3 text-slate-500\">Small groups, real itineraries, no filler days.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-sky-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Northern Portugal, 8 days</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-sky-600\">from $2,400</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Porto, the Douro Valley, and the Atlantic coast.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-sky-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Japan in Spring, 11 days</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-sky-600\">from $3,800</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Tokyo, Kyoto, and the Nakasendo trail.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-sky-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Peru Highlands, 9 days</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-sky-600\">from $2,950</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Cusco, the Sacred Valley, and Machu Picchu.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-sky-100 to-sky-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Morocco Overland, 10 days</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-sky-600\">from $2,600</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Marrakech, the Atlas Mountains, and the Sahara.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-sky-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">34</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Countries</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">2,100+</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Travelers hosted</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">4.9/5</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Trip rating</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-sky-300 md:text-4xl\">10</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Max group size</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Get trip details</h2>\n      <p className=\"mt-3 text-slate-500\">Tell us where you're dreaming of — we'll send full itineraries and pricing.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-sky-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-sky-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-sky-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Wanderlust Tours</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Small-group trips built around real local access.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Trips</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/destinations\" className=\"text-sm text-slate-500 hover:text-slate-900\">Destinations</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Company</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">About</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Reviews</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Wanderlust Tours. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-sky-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-sky-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Destinations","Stats","Footer"]},{"slug":"destinations","path":"/destinations","name":"Destinations","sections":["Navbar","Destinations","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
