gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-orange-600 px-6 py-3 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Browse courses</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">How cohorts work</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-orange-100 to-orange-50 ring-1 ring-orange-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Courses.tsx":"export default function Courses() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Upcoming cohorts</h2>\n        <p className=\"mt-3 text-slate-500\">Small classes, real projects, direct instructor feedback.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Intro to UX Design, 6 weeks</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$650</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">From research to a portfolio-ready case study.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Data Analysis with Python, 8 weeks</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$780</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Real datasets, real stakeholders, real deadlines.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Product Management 101, 5 weeks</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$540</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Ship a feature spec from problem to roadmap.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Copywriting for Startups, 4 weeks</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$390</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Write landing pages that actually convert.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-orange-50 text-slate-900\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-orange-300 md:text-4xl\">3,400+</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Graduates</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-orange-300 md:text-4xl\">92%</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Completion rate</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-orange-300 md:text-4xl\">18</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Avg. cohort size</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-orange-300 md:text-4xl\">4.8/5</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Course rating</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Get enrollment details</h2>\n      <p className=\"mt-3 text-slate-500\">We'll send the syllabus, schedule, and next cohort start date.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Campus Academy</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Small, instructor-led cohorts built around real projects.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Learn</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/courses\" className=\"text-sm text-slate-500 hover:text-slate-900\">Courses</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">About</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Instructors</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Outcomes</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Campus Academy. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-orange-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-orange-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Courses","Stats","Footer"]},{"slug":"courses","path":"/courses","name":"Courses","sections":["Navbar","Courses","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
  ('a95ccff3-c775-48e4-921b-07b84292e902', 'E-commerce', 'Loomwear', 'An editorial DTC fashion storefront landing page — dark hero, product grid, and a lookbook feel.', ARRAY['ecommerce', 'fashion', 'editorial', 'dtc']::text[], 'editorial', 'fashion retail', 'pro', false, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"uppercase tracking-widest text-sm text-lg font-bold tracking-tight text-slate-900\">LOOMWEAR</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/shop\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Shop</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-none bg-stone-600 px-4 py-2 text-sm font-semibold text-white hover:bg-stone-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-stone-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-stone-300\">New season, now live</span>\n        <h1 className=\"font-sans mt-6 text-4xl font-bold leading-tight tracking-tight md:text-6xl\">Clothes built to be worn for a decade, not a season.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Loomwear makes a small number of essentials from natural fibers, produced in limited runs — no seasonal landfill.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-stone-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-stone-400 transition-colors\">Shop the collection</a>\n          <a href=\"#features\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">Our materials</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Shop.tsx":"export default function Shop() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">The collection</h2>\n        <p className=\"mt-3 text-slate-500\">A capsule of eight pieces, restocked twice a year.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">The Everyday Tee</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$48</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Heavyweight organic cotton, boxy fit.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Field Jacket</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$228</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Waxed cotton canvas, brass hardware.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Wide-Leg Trouser</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$138</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Mid-weight wool blend, drapes clean.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Merino Crewneck</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$118</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Fine-gauge merino, naturally odor-resistant.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Selvedge Denim</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$188</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">13oz Japanese selvedge, raw hem.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-stone-100 to-stone-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Canvas Tote</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-stone-600\">$58</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Heavyweight canvas, leather straps.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Questions about an order?</h2>\n      <p className=\"mt-3 text-slate-500\">Our support team replies within one business day.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-stone-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-stone-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-stone-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-stone-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-stone-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">LOOMWEAR</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">A small collection of essentials, made to last.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Shop</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/shop\" className=\"text-sm text-slate-500 hover:text-slate-900\">All products</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Support</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Company</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Materials</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Shipping</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} LOOMWEAR. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-stone-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-stone-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Shop","Footer"]},{"slug":"shop","path":"/shop","name":"Shop","sections":["Navbar","Shop","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
  ('c4924fbc-096f-40ea-9e04-68734b96c0d1', 'Fitness', 'Forge Fitness', 'A high-energy gym/studio site — dark hero, class schedule grid, and a membership inquiry form.', ARRAY['fitness', 'gym', 'classes', 'energetic']::text[], 'energetic', 'fitness', 'free', false, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"uppercase tracking-wide text-sm text-lg font-bold tracking-tight text-slate-900\">FORGE</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/classes\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Classes</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Join</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-red-600 px-4 py-2 text-sm font-semibold text-white hover:bg-red-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-neutral-950 text-white\">\n      <div className=\"mx-auto max-w-3xl px-6 py-28 text-center md:py-36\">\n        <span className=\"inline-block rounded-full border border-white/15 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-red-300\">First class free</span>\n        <h1 className=\"font-sans mt-6 text-4xl font-bold leading-tight tracking-tight md:text-6xl\">Train like the plan actually matters.</h1>\n        <p className=\"mx-auto mt-5 max-w-xl text-lg text-white/60\">Forge runs coached strength and conditioning classes — real programming, real coaching, no wandering around a machine you don't know how to use.</p>\n        <div className=\"mt-9 flex flex-wrap items-center justify-center gap-3\">\n          <a href=\"/contact\" className=\"rounded-full bg-red-500 px-7 py-3 text-sm font-semibold text-slate-950 hover:bg-red-400 transition-colors\">Book a free class</a>\n          <a href=\"#features\" className=\"rounded-full border border-white/20 px-7 py-3 text-sm font-semibold hover:border-white/40 transition-colors\">See the schedule</a>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Classes.tsx":"export default function Classes() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Class schedule</h2>\n        <p className=\"mt-3 text-slate-500\">New members start with a free intro session.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-red-100 to-red-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Strength Fundamentals</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Mon/Wed/Fri, 6:00am & 5:30pm — squat, press, pull.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-red-100 to-red-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Conditioning</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Tue/Thu, 6:00am & 6:00pm — high-intensity intervals.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-red-100 to-red-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Open Gym</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Daily, 10:00am – 8:00pm — self-directed training.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-red-100 to-red-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Mobility & Recovery</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Sat, 9:00am — guided mobility work.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-neutral-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-red-300 md:text-4xl\">6</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Certified coaches</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-red-300 md:text-4xl\">18</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Classes per week</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-red-300 md:text-4xl\">2015</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Founded</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-red-300 md:text-4xl\">500+</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Active members</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Book your free class</h2>\n      <p className=\"mt-3 text-slate-500\">No commitment — just show up and see if it's the right fit.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-red-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-red-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-red-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-red-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-red-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Forge Fitness</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Coached strength and conditioning, real programming.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Train</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/classes\" className=\"text-sm text-slate-500 hover:text-slate-900\">Classes</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Join</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Gym</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Coaches</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Hours</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Forge Fitness. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-red-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-red-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Classes","Stats","Footer"]},{"slug":"classes","path":"/classes","name":"Classes","sections":["Navbar","Classes","Footer"]},{"slug":"contact","path":"/contact","name":"Join","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
  ('8b84ccf0-f4b8-4a1b-9fa8-24476553cf45', 'Nonprofit', 'Clearwater Initiative', 'A hopeful, impact-led nonprofit site — mission hero, impact stats, program grid, and a get-involved form.', ARRAY['nonprofit', 'cause', 'impact', 'hopeful']::text[], 'hopeful', 'nonprofit', 'business', false, $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-tight text-slate-900\">Clearwater</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/about\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">About</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Get involved</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-cyan-600 px-4 py-2 text-sm font-semibold text-white hover:bg-cyan-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-cyan-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-cyan-700\">Clean water access, since 2011</span>\n          <h1 className=\"font-sans mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">Clean water changes everything else.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Clearwater Initiative builds and maintains community water systems in underserved regions — every dollar is tracked to a specific well.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-cyan-600 px-6 py-3 text-sm font-semibold text-white hover:bg-cyan-700 transition-colors\">Donate today</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">See our impact</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-cyan-100 to-cyan-50 ring-1 ring-cyan-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-cyan-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-cyan-300 md:text-4xl\">312</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Wells built</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-cyan-300 md:text-4xl\">480k</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">People served</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-cyan-300 md:text-4xl\">94%</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Wells still active</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-cyan-300 md:text-4xl\">$0.86</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Of every $1 to programs</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Programs.tsx":"export default function Programs() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Where the work happens</h2>\n        <p className=\"mt-3 text-slate-500\">Current programs across three regions.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-cyan-100 to-cyan-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">East Rift Valley</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">42 wells built since 2019, community-maintained.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-cyan-100 to-cyan-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Northern Highlands</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Piped systems serving 6 villages, in progress.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-cyan-100 to-cyan-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">River Basin Region</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Water quality monitoring across 80 sites.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Get involved</h2>\n      <p className=\"mt-3 text-slate-500\">Volunteer, partner with us, or ask about corporate matching.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-cyan-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-cyan-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-cyan-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-cyan-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-cyan-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Clearwater Initiative</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Clean water access for underserved communities since 2011.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Learn</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/about\" className=\"text-sm text-slate-500 hover:text-slate-900\">About</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Get involved</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Give</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Donate</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Annual report</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Clearwater Initiative. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-cyan-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-cyan-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Stats","Programs","Footer"]},{"slug":"about","path":"/about","name":"About","sections":["Navbar","Stats","Programs","Footer"]},{"slug":"contact","path":"/contact","name":"Get involved","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb);
